import { Component, Input, Output, EventEmitter } from '@angular/core';

@Component({
  selector: 'app-button',
  standalone: true,
  template: `
    <button
      type="button"
      class="btn"
      [class.primary]="variant === 'primary'"
      [class.secondary]="variant === 'secondary'"
      [class.ghost]="variant === 'ghost'"
      [class.sm]="size === 'sm'"
      [class.md]="size === 'md'"
      [class.lg]="size === 'lg'"
      [class.is-loading]="loading"
      [attr.aria-disabled]="disabled || loading"
      [attr.aria-busy]="loading"
      [disabled]="disabled || loading"
      (click)="onClick($event)"
      (mousedown)="onPressStart()"
      (mouseup)="onPressEnd()"
      (mouseleave)="onPressEnd()"
      (touchstart)="onPressStart()"
      (touchend)="onPressEnd()"
    >
      <span class="leading-icon" *ngIf="icon_leading && !loading">{{ icon_leading }}</span>
      <span class="label" *ngIf="!loading">{{ label }}</span>
      <span class="spinner" *ngIf="loading" role="status" aria-label="loading"></span>
      <span class="meta" hidden>
        <span>{{ label }}</span>
        <span>{{ variant }}</span>
        <span>{{ size }}</span>
        <span>{{ disabled }}</span>
        <span>{{ loading }}</span>
        <span>{{ icon_leading }}</span>
      </span>
    </button>
  `,
  styles: [`
    .btn {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      border-radius: 6px;
      border: 1px solid transparent;
      cursor: pointer;
      font-weight: 500;
      transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;
    }
    .btn[disabled], .btn[aria-disabled='true'] {
      opacity: 0.6;
      cursor: not-allowed;
    }
    .btn.sm { padding: 0.25rem 0.5rem; font-size: 0.75rem; }
    .btn.md { padding: 0.5rem 0.75rem; font-size: 0.875rem; }
    .btn.lg { padding: 0.75rem 1rem; font-size: 1rem; }
    .btn.primary { background-color: #2563eb; color: #fff; }
    .btn.secondary { background-color: #e5e7eb; color: #111827; }
    .btn.ghost { background-color: transparent; color: #2563eb; border-color: transparent; }
    .btn.is-loading .label { visibility: hidden; }
    .spinner {
      display: inline-block;
      width: 1em;
      height: 1em;
      border: 2px solid currentColor;
      border-right-color: transparent;
      border-radius: 50%;
      animation: btn-spin 0.6s linear infinite;
    }
    @keyframes btn-spin {
      to { transform: rotate(360deg); }
    }
  `]
})
export class ButtonComponent {
  @Input() label: string = '';
  @Input() variant: 'primary' | 'secondary' | 'ghost' = 'primary';
  @Input() size: 'sm' | 'md' | 'lg' = 'md';
  @Input() disabled: boolean = false;
  @Input() loading: boolean = false;
  @Input() icon_leading?: string;

  @Output() pressed = new EventEmitter<void>();
  @Output() long_pressed = new EventEmitter<void>();

  private pressTimer: any = null;
  private readonly longPressDurationMs = 500;

  onClick(event: Event): void {
    if (this.disabled || this.loading) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
    this.pressed.emit();
  }

  onPressStart(): void {
    if (this.disabled || this.loading) {
      return;
    }
    this.clearTimer();
    this.pressTimer = setTimeout(() => {
      this.long_pressed.emit();
      this.pressTimer = null;
    }, this.longPressDurationMs);
  }

  onPressEnd(): void {
    this.clearTimer();
  }

  private clearTimer(): void {
    if (this.pressTimer !== null) {
      clearTimeout(this.pressTimer);
      this.pressTimer = null;
    }
  }
}
